import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { raster } from "./tokens.stylex";
import { rs } from "./rs";

export interface CalloutProps extends React.HTMLAttributes<HTMLDivElement> {}

const styles = stylex.create({
  box: {
    backgroundColor: raster.paper,
    borderWidth: raster.hairline,
    borderStyle: "solid",
    borderColor: raster.divider,
    borderRadius: 0,
    boxShadow: "none",
    paddingBlock: {
      default: 16,
      "@media (max-width: 640px)": 14,
    },
    paddingInline: {
      default: 20,
      "@media (max-width: 640px)": 16,
    },
  },
});

/** Paper field, 1px hairline on all sides. Not rounded. No left bar. */
export function Callout({ className, style, ...props }: CalloutProps) {
  const sx = rs(["rs-callout", className], styles.box);
  return <div {...props} className={sx.className} style={{ ...sx.style, ...style }} />;
}

import type { CSSProperties } from "react";
import * as stylex from "@stylexjs/stylex";
import { cx } from "./cx";

type StyleXProps = { className?: string; style?: CSSProperties };

/** Merge Raster class names with StyleX props. CSS-first classes stay on the node. */
export function rs(classNames: Array<string | false | null | undefined>, ...styles: unknown[]): StyleXProps {
  const sx = (stylex.props as (...args: unknown[]) => StyleXProps)(...styles);
  return {
    className: cx(...classNames, sx.className),
    style: sx.style,
  };
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Callout: paper field, 1px hairline on all sides. Not rounded. No left bar. ── */
.rs-callout{background:var(--bg);border:1px solid var(--divider);border-radius:0;box-shadow:none;padding:16px 20px}
.rs-callout p{font-size:14px;font-weight:500;color:var(--text-secondary);letter-spacing:-.01em;line-height:1.6;margin:0}
.rs-callout p strong{color:var(--text);font-weight:600}
@media(max-width:640px){.rs-callout{padding:14px 16px}}
